Here's the complete function, followed by a few notes on edge cases.

```python
import re
from datetime import datetime


def dedupe_contacts(rows):
    """Deduplicate CRM contact rows according to the data team's rules.

    Returns a list of merged person dicts with the keys first_name,
    last_name, email, phone, zip, tags, opted_out, updated, and source.
    """

    # ---------- normalizers ----------

    def norm_email(raw):
        s = raw or ""
        m = re.search(r"<([^<>]*)>", s)
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if s.count("@") == 1:
            local, domain = s.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.replace(".", "").split("+", 1)[0]
                s = local + "@gmail.com"
        return s

    def email_is_valid(e):
        if e.count("@") != 1:
            return False
        local, domain = e.split("@")
        return (
            local != ""
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def norm_phone(raw):
        s = raw or ""
        low = s.lower()
        cut = len(s)
        for marker in ("ext", "x", "#"):
            i = low.find(marker)
            if i != -1:
                cut = min(cut, i)
        digits = "".join(c for c in s[:cut] if c in "0123456789")
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    def phone_is_valid(p):
        return len(p) == 10 and p[0] not in "01"

    def norm_zip(raw):
        s = (raw or "").strip()
        m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", s)
        if m:
            s = m.group(1)
        if re.fullmatch(r"[0-9]{4}", s):
            s = "0" + s
        return s if re.fullmatch(r"[0-9]{5}", s) else ""

    def norm_name(raw):
        s = (raw or "").strip()
        if s.isupper() or s.islower():
            return s.title()
        return s

    def parse_updated(raw):
        s = (raw or "").strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unrecognized 'updated' value: {raw!r}")

    def is_opted_out(raw):
        return (raw or "").strip().lower() in ("y", "yes", "true", "1")

    def split_tags(raw):
        return [t.strip().lower() for t in re.split(r"[;,]", raw or "")]

    # ---------- normalize & filter (rule 9) ----------

    recs = []
    for idx, row in enumerate(rows):
        email = norm_email(row.get("email", ""))
        phone = norm_phone(row.get("phone", ""))
        email_ok = email_is_valid(email)
        phone_ok = phone_is_valid(phone)
        if not (email_ok or phone_ok):
            continue
        source = (row.get("source", "") or "").strip().lower()
        recs.append({
            "idx": idx,
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "first_name": norm_name(row.get("first_name", "")),
            "last_name": norm_name(row.get("last_name", "")),
            "zip": norm_zip(row.get("zip", "")),
            "source": source,
            "manual": source == "manual",
            "updated": parse_updated(row.get("updated", "")),
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "tags": split_tags(row.get("tags", "")),
        })

    # ---------- union-find (rule 10) ----------

    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Keep the smaller index as root (purely cosmetic).
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("email", r["email"]))
        if r["phone"] and r["last_name"]:
            keys.append(("phone", r["phone"], r["last_name"].casefold()))
        for k in keys:
            if k in first_seen:
                union(i, first_seen[k])
            else:
                first_seen[k] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(recs[i])

    # ---------- merge (rules 11 & 12) ----------

    def priority(r):
        # manual first, then most recent updated, then earliest input row
        dt = r["updated"]
        secs = dt.toordinal() * 86400 + dt.hour * 3600 + dt.minute * 60 + dt.second
        return (0 if r["manual"] else 1, -secs, r["idx"])

    def pick(members, field):
        candidates = [r for r in members if r[field]]
        if not candidates:
            return ""
        return min(candidates, key=priority)[field]

    people = []
    for members in groups.values():
        tags = set()
        for r in members:
            tags.update(t for t in r["tags"] if t)
        latest = max(r["updated"] for r in members)
        people.append((
            min(r["idx"] for r in members),
            {
                "first_name": pick(members, "first_name"),
                "last_name": pick(members, "last_name"),
                "email": pick(members, "email"),
                "phone": pick(members, "phone"),
                "zip": pick(members, "zip"),
                "tags": ";".join(sorted(tags)),
                "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
                "updated": f"{latest.year:04d}-{latest.month:02d}-{latest.day:02d}",
                "source": pick(members, "source"),
            },
        ))

    people.sort(key=lambda p: p[0])
    return [p[1] for p in people]
```

**Notes and judgment calls:**

- **Opted-out people are still in the output.** They appear with `opted_out = "Y"`, as the spec requires. Filter them out before the send, e.g. `[p for p in result if p["opted_out"] == "N"]`. Because merging is transitive, a single opted-out row suppresses the whole merged person, which is the safe behavior you want.
- **Each output row has at most one email, but separate people can share one.** Two rows with different emails that only match by phone and last name merge into one person with one chosen email. Rows that share a phone but have different (or missing) last names stay separate people. If you're sending by email, it's worth deduping the final send list on `email` as a last safety check.
- **ZIP+4 with a missing leading zero** (e.g. `2139-4307`) is treated as ZIP+4 and padded to `02139`. If you want strict 5+4 only, change `{4,5}` to `{5}` in the regex.
- **Extension markers:** the first occurrence of `ext`, `x`, or `#` cuts the phone. Note that this means any stray "x" in a phone field truncates it, per the rule as written.
- **Digits:** only ASCII 0–9 are counted, so Unicode digit characters won't slip through.
- **`updated`:** a malformed `updated` value raises a `ValueError` with the bad value rather than being silently guessed, so you'll notice data problems before the send.
- **Validity checks are lightweight.** The email check is the simple one from rule 2, so it won't catch every malformed address. Your email platform's own validation and bounce handling still apply.
